		body.u16(20);
		body.u16(UTF8_FLAG);
		body.u16(usedMethod);
		body.u16(time);
		body.u16(date);
		body.u32(crc);
		body.u32(payload.length);
		body.u32(data.length);
		body.u16(name.length);
		body.u16(0);
		body.bytes(name);
		body.bytes(payload);
		records.push({ name, crc, csize: payload.length, usize: data.length, offset, method: usedMethod, time, date });
