	for (const r of records) {
		central.u32(CENTRAL_SIG);
		central.u16(20);
		central.u16(20);
		central.u16(UTF8_FLAG);
		central.u16(r.method);
		central.u16(r.time);
		central.u16(r.date);
		central.u32(r.crc);
		central.u32(r.csize);
		central.u32(r.usize);
		central.u16(r.name.length);
		central.u16(0);
		central.u16(0);
		central.u16(0);
		central.u16(0);
		central.u32(0);
		central.u32(r.offset);
		central.bytes(r.name);
	}
	const centralBytes = central.toUint8Array();
