/** Live per-agent state captured while the process runs. */
interface AgentRecord {
	id: string;
	name: string;
	kind: string;
	depth: number;
	parentId?: string;
	model?: string;
	systemPrompt?: string[];
	tools?: string[];
	/** Latest async-job snapshot observed for this agent. */
	jobs?: unknown;
	startedAt: number;
	updatedAt: number;
	endedAt?: number;
