/** Build the archive zip for the calling session and write it to disk. */
async function writeArchive(ctx: ExtensionCommandContext, args: ArchiveArgs): Promise<{ outputPath: string; manifest: ArchiveManifest }> {
	const sessionFile = ctx.sessionManager.getSessionFile();
