		const mainJobs = probeJobs(ctx, ctx.agent.id);
		const jobs = {
			main: { agentId: ctx.agent.id, snapshot: mainJobs },
			agents: Object.fromEntries([...agents].map(([id, rec]) => [id, { agentId: id, snapshot: rec.jobs ?? null }])),
