				agent,
				entryId: entry.id,
				at: entry.timestamp,
				label: headline[1]!,
				status: attrs.status ?? headline[2],
				jobId: attrs.id,
				jobAgent: attrs.agent,
				duration: attrs.duration,
				lines: meta.lines,
				size: meta.size,
