		try {
			entries.push({ name: "viewer.html", data: new Uint8Array(await fs.readFile(opts.viewerHtmlPath)) });
		} catch (err) {
			omitted.push(`viewer.html: ${err instanceof Error ? err.message : String(err)}`);
		}
	}

