		subagents,
		artifacts,
		agents: summarizeAgents(opts.agents),
		jobs: { liveAgents, completed: jobs.completed.length, completedJobs: jobs.completed },
		totals: { files: entries.length + 2, bytes: aggregateBytes },
		omitted,
	};
