		`main: ${manifest.main.entries} entries`,
		`subagents: ${manifest.subagents.length}`,
		`artifacts: ${manifest.artifacts.length} files`,
		`total: ${manifest.totals.files} files, ${manifest.totals.bytes} bytes`,
	].join("\n");
}

